import{_ as t,o as d,c as o,a2 as n}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"AgentPay Unified Payment State Machine & Fault Recovery Specification (T1.1 Specification v2.1)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/state-machine.md","filePath":"specs/state-machine.md","lastUpdated":1792396280000}'),a={name:"specs/state-machine.md"};function c(i,e,r,l,s,u){return d(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="agentpay-unified-payment-state-machine-fault-recovery-specification-t1-1-specification-v2-1" tabindex="-1">AgentPay Unified Payment State Machine &amp; Fault Recovery Specification (T1.1 Specification v2.1) <a class="header-anchor" href="#agentpay-unified-payment-state-machine-fault-recovery-specification-t1-1-specification-v2-1" aria-label="Permalink to &quot;AgentPay Unified Payment State Machine &amp; Fault Recovery Specification (T1.1 Specification v2.1)&quot;">​</a></h1><blockquote><p><strong>Version</strong>: v2.1.0 (T1.1 Unified Specification: Dual-Rail Settlement Architecture)<br><strong>Status</strong>: <strong>Approved Specification</strong><br><strong>Prerequisites</strong>: T0.1 / T0.2 (Frozen baseline: <code>v0.1.0-poc-baseline</code>)<br><strong>Related Specification</strong>: <a href="./wallet-ledger">specs/wallet-ledger-spec.md</a> (T1.7 Virtual Wallet &amp; Ledger Specification)<br><strong>Machine-Readable Vectors</strong>: <a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/conformance/state-machine.json" target="_blank" rel="noreferrer"><code>specs/conformance/state-machine.json</code></a></p></blockquote><hr><h2 id="_1-core-design-principles" tabindex="-1">1. Core Design Principles <a class="header-anchor" href="#_1-core-design-principles" aria-label="Permalink to &quot;1. Core Design Principles&quot;">​</a></h2><ol><li><strong>Strict Orthogonal Separation of Three State Lines</strong>: <ul><li><strong>PaymentIntent</strong>: End-to-end business request lifecycle.</li><li><strong>Settlement</strong>: Fund transfer state supporting <strong>dual-rail payment methods (<code>Payment Method</code>)</strong>: <ul><li><code>onchain</code> (On-chain settlement): x402 challenge signing, blockchain broadcast, and block confirmation.</li><li><code>wallet</code> (Internal virtual wallet): Strongly transactional fund reservation (<code>Hold</code>), confirmed deduction (<code>Capture</code>), and reservation release (<code>Release</code>).</li></ul></li><li><strong>Fulfillment</strong>: Actual delivery state of the target upstream API resource/response.</li></ul></li><li><strong><code>unknown</code> as a First-Class State</strong>: <ul><li>Whenever a settlement or fulfillment outcome is ambiguous, <strong>it must never be assumed successful or assumed failed</strong>.</li><li>Wallet deductions execute within local database transactions and have no settlement <code>unknown</code> state; however, <strong>if fulfillment enters <code>unknown</code>, the wallet hold must remain locked and transition the intent to <code>needs_review</code></strong>—never auto-releasing or auto-capturing.</li></ul></li><li><strong>Terminal State Immutability</strong>: <ul><li>Once an entity enters a terminal state (<code>completed</code>, <code>failed</code>, <code>expired</code>, <code>rejected</code>, <code>confirmed</code>, <code>released</code>), its state is strictly read-only; only immutable audit events may be appended.</li></ul></li><li><strong>No Blind Retries &amp; No Silent Downgrades</strong>: <ul><li>Blindly re-charging or re-broadcasting an <code>unknown</code> state is strictly prohibited.</li><li><strong>No Auto-Downgrade</strong>: If a virtual wallet has insufficient balance, the gateway must immediately return <code>402 Insufficient Balance</code> and must never silently fall back to an on-chain charge, preventing unexpected on-chain expenditures.</li></ul></li></ol><hr><h2 id="_2-identifiers-multi-tenant-idempotency-contract" tabindex="-1">2. Identifiers &amp; Multi-Tenant Idempotency Contract <a class="header-anchor" href="#_2-identifiers-multi-tenant-idempotency-contract" aria-label="Permalink to &quot;2. Identifiers &amp; Multi-Tenant Idempotency Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Identifier</th><th>Scope &amp; Responsibility</th><th>Constraint Rules</th></tr></thead><tbody><tr><td><code>request_id</code></td><td>Single HTTP request trace</td><td>Generated by the gateway upon inbound arrival (UUIDv4) and propagated across all structured logs</td></tr><tr><td><code>idempotency_key</code></td><td>Client business-level idempotent retry</td><td>Unique per tenant. Identical keys within the same tenant strictly map to the same <code>payment_intent_id</code></td></tr><tr><td><code>payment_intent_id</code></td><td>High-level payment intent</td><td>One <code>idempotency_key</code> maps uniquely to one intent (format: <code>pi_...</code>)</td></tr><tr><td><code>hold_id</code></td><td>Virtual wallet reservation ID</td><td>Exclusive to the wallet path; one intent binds uniquely to one active Hold (format: <code>hld_...</code>)</td></tr><tr><td><code>settlement_id</code></td><td>Settlement record ID</td><td>One intent corresponds to at most one active settlement at any time (format: <code>stl_...</code>)</td></tr><tr><td><code>fulfillment_id</code></td><td>Upstream business delivery attempt</td><td>One intent corresponds strictly to one fulfillment record (format: <code>ful_...</code>)</td></tr></tbody></table><hr><h2 id="_3-dual-rail-settlement-fulfillment-state-flows" tabindex="-1">3. Dual-Rail Settlement &amp; Fulfillment State Flows <a class="header-anchor" href="#_3-dual-rail-settlement-fulfillment-state-flows" aria-label="Permalink to &quot;3. Dual-Rail Settlement &amp; Fulfillment State Flows&quot;">​</a></h2><h3 id="_3-1-on-chain-settlement-path" tabindex="-1">3.1 On-Chain Settlement Path <a class="header-anchor" href="#_3-1-on-chain-settlement-path" aria-label="Permalink to &quot;3.1 On-Chain Settlement Path&quot;">​</a></h3><p>Follows <strong>Scheme A (Settle Before Fulfill)</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authorized ──▶ submit ──▶ [submitted] ──▶ [pending] ──▶ [confirmed]</span></span>
<span class="line"><span>                                                             │ (dispatch)</span></span>
<span class="line"><span>                                                             ▼</span></span>
<span class="line"><span>                                                    [fulfillment: in_progress]</span></span>
<span class="line"><span>                                                             ├─ 2xx ─▶ completed</span></span>
<span class="line"><span>                                                             ├─ 4xx ─▶ refund_required</span></span>
<span class="line"><span>                                                             └─ 5xx ─▶ needs_review</span></span></code></pre></div><h3 id="_3-2-internal-virtual-wallet-path" tabindex="-1">3.2 Internal Virtual Wallet Path <a class="header-anchor" href="#_3-2-internal-virtual-wallet-path" aria-label="Permalink to &quot;3.2 Internal Virtual Wallet Path&quot;">​</a></h3><p>Follows the <strong>&quot;Hold → Fulfill → Capture / Release&quot;</strong> closed loop:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>authorized ──▶ hold ──▶ [held] ──(dispatch)──▶ [fulfillment: in_progress]</span></span>
<span class="line"><span>                                                        ├─ 2xx ─▶ capture ──▶ confirmed (completed)</span></span>
<span class="line"><span>                                                        ├─ 4xx ─▶ release ──▶ released (unbilled release)</span></span>
<span class="line"><span>                                                        └─ 5xx ─▶ keep held ──▶ needs_review (manual review)</span></span></code></pre></div><p><strong>Dual-Rail Advantage</strong>:</p><ul><li>In the wallet path, when the upstream explicitly fails with a 4xx error, the gateway simply executes an in-database transactional <code>release</code> to unfreeze the hold—<strong>eliminating complex refund or compensation workflows</strong>, guaranteeing zero financial loss for the buyer and zero unpaid service delivery for the seller.</li></ul><hr><h2 id="_4-three-dimensional-state-definitions-valid-transition-matrix" tabindex="-1">4. Three-Dimensional State Definitions &amp; Valid Transition Matrix <a class="header-anchor" href="#_4-three-dimensional-state-definitions-valid-transition-matrix" aria-label="Permalink to &quot;4. Three-Dimensional State Definitions &amp; Valid Transition Matrix&quot;">​</a></h2><h3 id="_4-1-payment-intent-paymentintent" tabindex="-1">4.1 Payment Intent (<code>PaymentIntent</code>) <a class="header-anchor" href="#_4-1-payment-intent-paymentintent" aria-label="Permalink to &quot;4.1 Payment Intent (\`PaymentIntent\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Current State</th><th>Trigger Event</th><th>Target State</th><th>Description &amp; Guard Conditions</th></tr></thead><tbody><tr><td><code>created</code></td><td><code>challenge_issued</code></td><td><code>challenged</code></td><td>On-chain path only: HTTP 402 challenge sent</td></tr><tr><td><code>created</code></td><td><code>payload_verified</code></td><td><code>authorized</code></td><td>Wallet path only: API Key and budget checks passed</td></tr><tr><td><code>created</code></td><td><code>policy_denied</code></td><td><code>rejected</code></td><td>Denied by policy, blocked by risk control, or wallet frozen in arrears</td></tr><tr><td><code>challenged</code></td><td><code>payload_verified</code></td><td><code>authorized</code></td><td>On-chain path: buyer retries request with valid signature</td></tr><tr><td><code>challenged</code></td><td><code>payload_invalid</code></td><td><code>rejected</code></td><td>Invalid signature, tampered payload, or malformed format</td></tr><tr><td><code>challenged</code></td><td><code>timeout</code></td><td><code>expired</code></td><td>Challenge TTL (default 300s) elapsed without submission</td></tr><tr><td><code>authorized</code></td><td><code>settlement_confirmed</code></td><td><code>completed</code></td><td>On-chain <code>confirmed</code> + fulfillment succeeded, or wallet <code>capture</code> succeeded</td></tr><tr><td><code>authorized</code></td><td><code>settlement_failed</code></td><td><code>failed</code></td><td>On-chain settlement failed, or insufficient wallet balance for hold</td></tr><tr><td><code>authorized</code></td><td><code>settlement_released</code></td><td><code>failed</code></td><td>Wallet path: hold released after upstream failure; intent closed unbilled</td></tr><tr><td><code>authorized</code></td><td><code>authorization_expired</code></td><td><code>expired</code></td><td>On-chain authorization expired before settlement started</td></tr><tr><td><code>authorized</code></td><td><code>recovery_deadline_exceeded</code></td><td><code>needs_review</code></td><td>Settlement or fulfillment remained <code>unknown</code> past recovery deadline</td></tr><tr><td><code>needs_review</code></td><td><code>manual_resolved_confirmed</code></td><td><code>completed</code></td><td>Manual operator verification confirmed payment and delivery</td></tr><tr><td><code>needs_review</code></td><td><code>manual_resolved_failed</code></td><td><code>failed</code></td><td>Manual operator verification confirmed non-delivery and closed intent</td></tr></tbody></table><h3 id="_4-2-settlement-settlement" tabindex="-1">4.2 Settlement (<code>Settlement</code>) <a class="header-anchor" href="#_4-2-settlement-settlement" aria-label="Permalink to &quot;4.2 Settlement (\`Settlement\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Current State</th><th>Trigger Event</th><th>Target State</th><th>Payment Method &amp; Rule</th></tr></thead><tbody><tr><td><code>not_started</code></td><td><code>hold_acquired</code></td><td><code>held</code></td><td>[Wallet] Quota successfully frozen in database transaction</td></tr><tr><td><code>not_started</code></td><td><code>hold_failed</code></td><td><code>failed</code></td><td>[Wallet] Insufficient available balance or wallet frozen</td></tr><tr><td><code>held</code></td><td><code>capture</code></td><td><code>confirmed</code></td><td>[Wallet] Upstream returned 2xx; deduction captured to ledger (terminal)</td></tr><tr><td><code>held</code></td><td><code>release</code></td><td><code>released</code></td><td>[Wallet] Upstream returned 4xx; hold released back to available balance (terminal)</td></tr><tr><td><code>not_started</code></td><td><code>submit_ok</code></td><td><code>submitted</code></td><td>[On-Chain] Broadcast succeeded and returned <code>tx_hash</code></td></tr><tr><td><code>not_started</code></td><td><code>submit_rejected_definitely</code></td><td><code>failed</code></td><td>[On-Chain] Deterministically rejected by RPC node</td></tr><tr><td><code>not_started</code></td><td><code>submit_timeout</code></td><td><code>unknown</code></td><td>[On-Chain] Submission timed out; state unknown</td></tr><tr><td><code>submitted</code></td><td><code>seen_on_chain</code></td><td><code>pending</code></td><td>[On-Chain] Transaction observed in mempool or mined block</td></tr><tr><td><code>submitted</code></td><td><code>query_timeout</code></td><td><code>unknown</code></td><td>[On-Chain] Receipt query timed out</td></tr><tr><td><code>pending</code></td><td><code>confirmations_reached</code></td><td><code>confirmed</code></td><td>[On-Chain] Reached required block confirmations (terminal)</td></tr><tr><td><code>pending</code></td><td><code>reverted</code></td><td><code>failed</code></td><td>[On-Chain] Transaction execution reverted on-chain (terminal)</td></tr><tr><td><code>pending</code></td><td><code>query_timeout</code></td><td><code>unknown</code></td><td>[On-Chain] Confirmation polling timed out</td></tr><tr><td><code>unknown</code></td><td><code>query_found_confirmed</code></td><td><code>confirmed</code></td><td>[On-Chain] Reconciliation probe confirmed block inclusion</td></tr><tr><td><code>unknown</code></td><td><code>query_found_failed</code></td><td><code>failed</code></td><td>[On-Chain] Reconciliation probe confirmed failure and expired unspent</td></tr><tr><td><code>unknown</code></td><td><code>query_found_pending</code></td><td><code>pending</code></td><td>[On-Chain] Pending transaction rediscovered on-chain</td></tr><tr><td><code>unknown</code></td><td><code>query_still_unknown</code></td><td><code>unknown</code></td><td>[On-Chain] Transaction state remains unknown</td></tr></tbody></table><h3 id="_4-3-business-fulfillment-fulfillment" tabindex="-1">4.3 Business Fulfillment (<code>Fulfillment</code>) <a class="header-anchor" href="#_4-3-business-fulfillment-fulfillment" aria-label="Permalink to &quot;4.3 Business Fulfillment (\`Fulfillment\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Current State</th><th>Trigger Event</th><th>Target State</th><th>Description &amp; Safety Guards</th></tr></thead><tbody><tr><td><code>not_started</code></td><td><code>dispatch</code></td><td><code>in_progress</code></td><td>Requires <code>settlement==confirmed</code> (on-chain) or <code>settlement==held</code> (wallet)</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_2xx</code></td><td><code>succeeded</code></td><td>Upstream delivery succeeded (triggers wallet <code>capture</code>)</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_4xx</code></td><td><code>failed</code></td><td>Upstream rejected client input without execution (triggers wallet <code>release</code>)</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_5xx</code></td><td><code>unknown</code></td><td>Upstream server error; cannot assume unexecuted (wallet keeps <code>held</code>)</td></tr><tr><td><code>in_progress</code></td><td><code>upstream_timeout</code></td><td><code>unknown</code></td><td>Connection dropped or read timed out (wallet keeps <code>held</code>)</td></tr><tr><td><code>unknown</code></td><td><code>upstream_status_query_ok</code></td><td><code>succeeded</code></td><td>Idempotent probe confirmed upstream succeeded (triggers delayed <code>capture</code>)</td></tr><tr><td><code>unknown</code></td><td><code>upstream_status_query_failed</code></td><td><code>failed</code></td><td>Idempotent probe confirmed upstream did not execute (triggers delayed <code>release</code>)</td></tr><tr><td><code>unknown</code></td><td><code>recovery_deadline_exceeded</code></td><td><code>unknown</code></td><td>Exceeded max recovery window; flagged for manual review</td></tr></tbody></table><hr><h2 id="_5-external-composite-view-mapping" tabindex="-1">5. External Composite View Mapping <a class="header-anchor" href="#_5-external-composite-view-mapping" aria-label="Permalink to &quot;5. External Composite View Mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Settlement State</th><th>Fulfillment State</th><th>Derived Display Status</th><th>Business Interpretation</th></tr></thead><tbody><tr><td><code>held</code></td><td><code>not_started</code> / <code>in_progress</code></td><td><code>WALLET_HOLD_PROCESSING</code></td><td>Wallet quota reserved; upstream service call in progress</td></tr><tr><td><code>unknown</code> / <code>pending</code> / <code>submitted</code></td><td><code>not_started</code></td><td><code>SETTLEMENT_IN_PROGRESS</code></td><td>On-chain payment settlement in progress</td></tr><tr><td><code>confirmed</code></td><td><code>in_progress</code></td><td><code>FULFILLMENT_IN_PROGRESS</code></td><td>Payment confirmed; upstream service delivery in progress</td></tr><tr><td><code>confirmed</code></td><td><code>succeeded</code></td><td><code>COMPLETED</code></td><td>Transaction and fulfillment completed successfully</td></tr><tr><td><code>confirmed</code></td><td><code>failed</code></td><td><code>SETTLED_FULFILLMENT_FAILED_REFUND_REQUIRED</code></td><td>On-chain payment settled but fulfillment failed; refund required</td></tr><tr><td><code>confirmed</code></td><td><code>unknown</code></td><td><code>SETTLED_FULFILLMENT_UNKNOWN_NEEDS_REVIEW</code></td><td>Payment confirmed, but fulfillment outcome is ambiguous and needs review</td></tr><tr><td><code>released</code></td><td><code>failed</code></td><td><code>RELEASED_UNBILLED</code></td><td>Wallet hold released; zero funds deducted</td></tr><tr><td><code>failed</code></td><td><code>not_started</code></td><td><code>PAYMENT_FAILED</code></td><td>Payment failed prior to fulfillment; zero funds deducted</td></tr></tbody></table>`,29)])])}const h=t(a,[["render",c]]);export{m as __pageData,h as default};
